#!/usr/bin/env python3
"""Assemble the standalone Bash release; no external baseline is required."""
from pathlib import Path
import hashlib
import subprocess

ROOT = Path(__file__).resolve().parents[1]
MODULES = [
    "core.sh", "validation.sh", "filesystem.sh", "gai.sh", "confirmation.sh",
    "adapters/dns.sh", "adapters/routing.sh", "adapters/ipv6.sh", "adapters/pool.sh",
    "adapters/nft.sh", "adapters/nat66.sh", "adapters/ssh.sh", "adapters/runtime.sh",
    "transaction.sh", "recovery/supervisor.sh", "main.sh",
]
HEADER = r"""#!/bin/bash
# DMITBox local safety refactor. Generated by build/build.py; edit src/ instead.
set -u -o pipefail
IFS=$' \t\n'
umask 077
PATH=/usr/sbin:/usr/bin:/sbin:/bin
export PATH
unset BASH_ENV ENV CDPATH GLOBIGNORE
LC_ALL=C
export LC_ALL
readonly DMB_VERSION='4.0.0-dev'
DMB_STATE_DIR=/var/lib/dmitbox-local
DMB_CONFIG_DIR=/etc/dmitbox-local
DMB_RUNTIME_DIR=/run/dmitbox-local
DMB_LOCK_DIR=/run/dmitbox-local/locks
DMB_ETC_ROOT=/etc
DMB_RUN_ROOT=/run
DMB_ARTIFACT=$(readlink -f -- "${BASH_SOURCE[0]}") || exit 78
readonly DMB_STATE_DIR DMB_CONFIG_DIR DMB_RUNTIME_DIR DMB_LOCK_DIR DMB_ETC_ROOT DMB_RUN_ROOT DMB_ARTIFACT
declare -a DMB_LOCK_FDS=()
"""

def main():
    parts = [HEADER]
    for name in MODULES:
        source = ROOT / "src" / name
        if not source.is_file():
            raise SystemExit(f"Missing module: {source}")
        text = source.read_text()
        if text.startswith("#!"):
            text = text.split("\n", 1)[1]
        parts.append(f"\n# BEGIN MODULE {name}\n{text.rstrip()}\n# END MODULE {name}\n")
    parts.append('\ndmb_main "$@"\n')
    data = "".join(parts).encode()
    out = ROOT / "dist"
    out.mkdir(exist_ok=True)
    target = out / "dmitbox-local.sh"
    target.write_bytes(data)
    target.chmod(0o700)
    subprocess.run(["bash", "-n", str(target)], check=True)
    digest = hashlib.sha256(data).hexdigest()
    (out / "SHA256SUMS").write_text(f"{digest}  dmitbox-local.sh\n")
    print(f"{target} ({len(data)} bytes, SHA256 {digest})")

if __name__ == "__main__":
    main()
